import XCTest
@testable import TapsoTransit

/// NightGuard decoding and lines. The payload is `GET /v1/night-guard` output
/// generated by the server's `nightGuardView` from a SYNTHETIC timetable
/// (invented places and times), read at Friday 22:30 KST.
final class NightGuardTests: XCTestCase {
    static let payload = #"""
{"item":{"schemaVersion":"tapso-night-guard-v1","routeNo":"999","label":"OFFICIAL_DATED","evaluatedAt":"2026-11-13T13:30:00.000Z","localDate":"2026-11-13","localTime":"22:30","asOf":"2026-11-01","freshness":"fresh","validUntil":"2026-11-13T14:01:00.000Z","entries":[{"direction":"합성A→합성B","scheduleId":"SYN","serviceDate":"2026-11-13","dayType":"weekday","dayLabel":"평일","applicability":"applies","measuredAt":{"kind":"trip_start"},"claimsOperating":false,"status":"before_first_departure","evidence":"OFFICIAL_DATED","next":{"table":"23:00","clock":"23:00","date":"2026-11-13","at":"합성A","minutesFromNow":30},"last":{"table":"24:10","clock":"00:10","date":"2026-11-14","at":"합성A","minutesFromNow":100},"laterConditional":[],"reasons":["measured_from_trip_start","scheduled_not_observed"]},{"direction":"합성B→합성A","scheduleId":"SYN","serviceDate":"2026-11-13","dayType":"weekday","dayLabel":"평일","applicability":"applies","measuredAt":{"kind":"trip_start"},"claimsOperating":false,"status":"last_scheduled_departed","evidence":"OFFICIAL_DATED","next":null,"last":{"table":"22:00","clock":"22:00","date":"2026-11-13","at":"합성A","minutesFromNow":-30},"laterConditional":[],"reasons":["measured_from_trip_start","bus_may_run_late"]},{"direction":"합성C→합성D","scheduleId":"SYN","serviceDate":"2026-11-13","dayType":"weekday","dayLabel":"평일","applicability":"applies","measuredAt":{"kind":"trip_start"},"claimsOperating":false,"status":"unknown","evidence":"CONFLICTED","next":null,"last":null,"laterConditional":[],"reasons":["measured_from_trip_start","source_conflict"]}],"reasons":[],"provenance":{"page":"https://synthetic.invalid","dataset":"SYNTHETIC","bundleVersion":"synthetic","parser":{"name":"synthetic","version":"1"},"retrievedAt":"2026-11-01T10:00:00+09:00"}}}
"""#

    private func view() throws -> TransitAPINightGuard {
        try JSONDecoder().decode(TransitAPINightGuardResponse.self, from: Data(Self.payload.utf8)).item
    }

    func testDecodesTheServerShape() throws {
        let view = try view()
        XCTAssertEqual(view.routeNo, "999")
        XCTAssertEqual(view.asOf, "2026-11-01")
        XCTAssertEqual(view.entries.count, 3)
        XCTAssertTrue(view.entries.allSatisfy { !$0.claimsOperating })
    }

    func testOnlyOfficialAnswersBecomeLines() throws {
        let decoded = try view()
        let lines = NightGuardLine.lines(decoded)
        XCTAssertEqual(lines.count, 2, "the conflicting table gives no line")
        let first = try XCTUnwrap(decoded.entries[0].next)
        XCTAssertEqual(lines[0].kind, .beforeFirst(first))
        XCTAssertEqual(first.table, "23:00")
        guard case let .lastDeparted(last) = lines[1].kind else { return XCTFail("expected lastDeparted") }
        XCTAssertEqual(last.table, "22:00")
        XCTAssertEqual(last.minutesFromNow, -30)
    }

    func testAnEntryClaimingOperationIsDropped() throws {
        let tampered = Self.payload.replacingOccurrences(of: #""claimsOperating":false"#, with: #""claimsOperating":true"#)
        let view = try JSONDecoder().decode(TransitAPINightGuardResponse.self, from: Data(tampered.utf8)).item
        XCTAssertEqual(NightGuardLine.lines(view), [], "TAPSO never shows a timetable as a running bus")
    }

    func testANextDayTimeReadsAsTheNextDay() {
        XCTAssertEqual(TimetableClock.display("24:10").text, "00:10")
        XCTAssertTrue(TimetableClock.display("24:10").nextDay)
    }
}
